{
  "tasks": [
    {
      "task_id": "T01",
      "title": "已完成任务中各项目工时总和（排除丙项目）",
      "business_question": "统计状态为“已完成”且项目不为“丙”的任务，按项目分组计算工时总和。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：统计已完成任务中各项目的工时总和并排除特定项目。若删除此任务，无法获取关键决策数据。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0002",
                "operator": "ne",
                "value": "丙"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
